-- Optional new application migration after 0001_core.sql; D1 RLS is unavailable.
-- Every query MUST bind tenant_id from verified backend session and use durable transactions.
CREATE TABLE IF NOT EXISTS payment_intents(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),provider TEXT NOT NULL,provider_order_id TEXT,order_id TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL,quote_snapshot_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,provider,provider_order_id),UNIQUE(tenant_id,order_id,provider));
CREATE TABLE IF NOT EXISTS payment_transactions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),intent_id TEXT NOT NULL REFERENCES payment_intents(id),provider TEXT NOT NULL,provider_payment_id TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL,occurred_at TEXT NOT NULL,UNIQUE(tenant_id,provider,provider_payment_id));
CREATE TABLE IF NOT EXISTS payment_refunds(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),transaction_id TEXT NOT NULL REFERENCES payment_transactions(id),provider_refund_id TEXT,client_idempotency_key TEXT NOT NULL,requested_minor INTEGER NOT NULL CHECK(requested_minor>0),fee_deduction_minor INTEGER NOT NULL DEFAULT 0 CHECK(fee_deduction_minor>=0),provider_refund_minor INTEGER NOT NULL CHECK(provider_refund_minor>=0),reason TEXT NOT NULL,requested_by TEXT NOT NULL,approved_by TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(requested_minor=fee_deduction_minor+provider_refund_minor),UNIQUE(tenant_id,client_idempotency_key),UNIQUE(tenant_id,provider_refund_id));
CREATE TABLE IF NOT EXISTS payment_ledger(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),transaction_id TEXT,refund_id TEXT,entry_type TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,external_event_key TEXT NOT NULL,recorded_at TEXT NOT NULL,recorded_by TEXT NOT NULL,reason TEXT,UNIQUE(tenant_id,external_event_key));
CREATE TABLE IF NOT EXISTS payment_settlements(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),provider TEXT NOT NULL,settlement_ref TEXT NOT NULL,transaction_id TEXT NOT NULL REFERENCES payment_transactions(id),net_minor INTEGER NOT NULL CHECK(net_minor>=0),platform_fee_minor INTEGER NOT NULL DEFAULT 0,processing_fee_minor INTEGER NOT NULL DEFAULT 0,partner_payout_minor INTEGER NOT NULL CHECK(partner_payout_minor>=0),currency TEXT NOT NULL,status TEXT NOT NULL,CHECK(net_minor=platform_fee_minor+processing_fee_minor+partner_payout_minor),UNIQUE(tenant_id,provider,settlement_ref,transaction_id));
CREATE INDEX IF NOT EXISTS idx_payment_intents_order ON payment_intents(tenant_id,order_id);
CREATE INDEX IF NOT EXISTS idx_payment_refunds_transaction ON payment_refunds(tenant_id,transaction_id,status);
CREATE INDEX IF NOT EXISTS idx_payment_ledger_time ON payment_ledger(tenant_id,recorded_at DESC);
